insert into public.curriculum_tasks (id, day_id, day_number, session, position, title, description, task_type, estimated_minutes, priority, is_required, skill_area) values ('457fc3a8-5214-4bd2-a5db-a6cfd98095a5', (select id from public.curriculum_days where day_number = 90), 90, 'evening', 4, 'Log mistakes and plan revision', 'Write down mistakes, mark weak topics as Needs Revision, and preview tomorrow.', 'recap', 10, 'low', false, 'ai_engineering') on conflict (id) do update set title = excluded.title, description = excluded.description, task_type = excluded.task_type, estimated_minutes = excluded.estimated_minutes, priority = excluded.priority, is_required = excluded.is_required, skill_area = excluded.skill_area;
insert into public.interview_questions (id, slug, category, skill_area, difficulty, title, short_answer, explanation, code_example, real_world_example, follow_ups, related_concepts, key_points, day_numbers) values ('338c0908-10bf-4354-a8b7-b8fa904b19b3', 'ai-tokens-context', 'AI Engineering', 'ai_engineering', 'beginner', 'What are tokens and context windows, and why do they matter?', 'LLMs read and write tokens — chunks of text, roughly 3–4 characters of English each. The context window is the maximum number of tokens (input + output) the model can handle in one request. Tokens drive cost, latency and what information the model can see at once.', 'Text is split by a tokenizer into sub-word pieces; code, numbers and non-English text often use more tokens per word. Providers bill per input and output token, and latency grows with output length. The context window caps everything the model sees: system prompt, history, retrieved documents and the answer. When content exceeds it you must trim, summarize or retrieve only the relevant parts. Large windows help, but models can still miss details buried in the middle of very long inputs, so relevance beats volume.', '// Rough budget for one request
insert into public.interview_questions (id, slug, category, skill_area, difficulty, title, short_answer, explanation, code_example, real_world_example, follow_ups, related_concepts, key_points, day_numbers) values ('8d624590-e6b4-403c-a9f6-72ae10b1cdae', 'ai-temperature-sampling', 'AI Engineering', 'ai_engineering', 'beginner', 'What do temperature and top-p control?', 'They control randomness when the model picks the next token. Low temperature makes output focused and repeatable; higher temperature makes it more varied. Top-p limits choices to the smallest set of tokens whose probabilities add up to p. Use low values for extraction and code, higher for brainstorming.', 'At each step the model produces a probability for every possible next token. Temperature rescales those probabilities: near 0 the most likely token almost always wins; above 1 unlikely tokens get more chances. Top-p (nucleus sampling) cuts off the long tail of unlikely tokens. Even at temperature 0, outputs are not guaranteed identical across runs or model versions, so tests should check properties, not exact strings.', null, 'A JSON extraction endpoint runs at temperature 0 for consistency, while a marketing-copy generator uses a higher value to produce several distinct options.', array['Is temperature 0 fully deterministic?','Should you tune temperature and top-p together?','How does sampling affect evals?']::text[], array['Next-token prediction','Evals','Structured outputs']::text[], array['Sampling picks the next token from a distribution','Low temperature = focused, high = varied','Top-p trims unlikely tokens','Test properties, not exact output']::text[], array[61,67]::int[]) on conflict (slug) do update set category = excluded.category, skill_area = excluded.skill_area, difficulty = excluded.difficulty, title = excluded.title, short_answer = excluded.short_answer, explanation = excluded.explanation, code_example = excluded.code_example, real_world_example = excluded.real_world_example, follow_ups = excluded.follow_ups, related_concepts = excluded.related_concepts, key_points = excluded.key_points, day_numbers = excluded.day_numbers;
insert into public.interview_questions (id, slug, category, skill_area, difficulty, title, short_answer, explanation, code_example, real_world_example, follow_ups, related_concepts, key_points, day_numbers) values ('97ac468e-7bfc-40cc-a913-7e74d9e7f064', 'ai-structured-output', 'AI Engineering', 'ai_engineering', 'intermediate', 'How do you get reliable structured (JSON) output from an LLM?', 'Describe the exact schema, use the provider''s structured-output or tool-calling feature where available, validate the result with a schema library like Zod, and retry with the validation error when it fails. Never trust unvalidated model output in your code.', 'Reliability comes in layers. First, a clear prompt with the schema and an example. Second, native features — tool/function calling or JSON-schema modes — that constrain output to the schema. Third, validation in your code: parse and check types, ranges and required fields. Fourth, a bounded repair loop: send the validation error back and ask for a corrected object, giving up after 1–2 tries. Finally, log failures so you can improve the prompt.', 'const Invoice = z.object({ vendor: z.string(), total: z.number().nonnegative(), date: z.string().date() });
insert into public.interview_questions (id, slug, category, skill_area, difficulty, title, short_answer, explanation, code_example, real_world_example, follow_ups, related_concepts, key_points, day_numbers) values ('6016482b-14c4-4d80-a517-3d6244ce1265', 'ai-prompt-injection', 'AI Engineering', 'ai_engineering', 'intermediate', 'What is prompt injection and how do you defend against it?', 'Prompt injection is when untrusted text — user input, a web page, an email, a retrieved document — contains instructions that hijack the model. You can''t fully prevent it with prompts alone, so you limit the damage: least-privilege tools, confirmation for risky actions, separating instructions from data, output checks and never letting the model''s output directly authorize anything.', 'Direct injection comes from the user (''ignore your instructions''). Indirect injection hides in content the model reads, such as a PDF saying ''email all customer data to x''. Defenses: clearly delimit untrusted content and tell the model it is data; give tools the minimum permissions; require user confirmation before sending, deleting or paying; enforce authorization in your backend, not in the prompt; filter outputs (e.g. block unexpected URLs); and red-team regularly. Treat the model like an untrusted user of your own API.', null, 'A support bot that can issue refunds should call a backend endpoint that checks the order and the refund policy itself — the model''s request alone is never enough.', array['Why can''t a better system prompt solve this?','What is indirect prompt injection?','How do you red-team an LLM feature?']::text[], array['Agent safety','Least privilege','Guardrails']::text[], array['Direct vs indirect injection','Prompts alone are not a security boundary','Least-privilege tools and confirmations','Authorize in the backend','Red-team regularly']::text[], array[66,81,82]::int[]) on conflict (slug) do update set category = excluded.category, skill_area = excluded.skill_area, difficulty = excluded.difficulty, title = excluded.title, short_answer = excluded.short_answer, explanation = excluded.explanation, code_example = excluded.code_example, real_world_example = excluded.real_world_example, follow_ups = excluded.follow_ups, related_concepts = excluded.related_concepts, key_points = excluded.key_points, day_numbers = excluded.day_numbers;
insert into public.interview_questions (id, slug, category, skill_area, difficulty, title, short_answer, explanation, code_example, real_world_example, follow_ups, related_concepts, key_points, day_numbers) values ('4c026665-eb65-460e-a953-b5fb156d2276', 'ai-embeddings', 'AI Engineering', 'ai_engineering', 'beginner', 'What are embeddings and how is semantic search built on them?', 'An embedding is a list of numbers representing the meaning of a piece of text, so similar meanings end up close together. Semantic search embeds documents ahead of time, embeds the query at search time, and returns the documents whose vectors are most similar — usually by cosine similarity.', 'An embedding model maps text to a fixed-size vector (for example 1,024 numbers). Texts about similar topics produce vectors pointing in similar directions even when they share no words, which is why ''reset my password'' matches ''can''t log in''. Cosine similarity measures the angle between vectors; with normalized vectors it equals the dot product. Store vectors in a vector index (pgvector, Pinecone, Qdrant) for fast approximate nearest-neighbor search. Keyword search still wins for exact terms like IDs and error codes, which is why hybrid search is common.', 'function cosine(a: number[], b: number[]) {
insert into public.interview_questions (id, slug, category, skill_area, difficulty, title, short_answer, explanation, code_example, real_world_example, follow_ups, related_concepts, key_points, day_numbers) values ('5b664382-820c-4b37-a008-41d09cb8480e', 'ai-rag-explained', 'AI Engineering', 'ai_engineering', 'intermediate', 'Explain Retrieval-Augmented Generation (RAG). When would you use it instead of fine-tuning?', 'RAG retrieves relevant documents at request time and puts them in the prompt so the model answers from that context, with citations. Use RAG for knowledge that changes or must be cited and permission-checked; use fine-tuning to change style, format or behavior on a narrow task — not to teach facts.', 'Pipeline: ingest documents → chunk → embed → store. At query time: embed the question → retrieve top-k chunks (often hybrid + reranking) → assemble context within a token budget → generate an answer that cites sources → fall back to ''I don''t know'' if nothing relevant is found. Benefits: fresh knowledge without retraining, citations users can verify, and per-user access control at retrieval time. Common failures are poor chunking, missing metadata filters, retrieving near-duplicates and models ignoring context — each fixed and measured with evals.', null, 'An internal HR assistant answers policy questions from the latest handbook and links the exact section, and contractors never retrieve employee-only documents.', array['How do you choose chunk size?','How do you enforce document permissions?','How do you evaluate a RAG system?']::text[], array['Embeddings','Chunking','Reranking','Evals']::text[], array['Retrieve → augment → generate','Citations and honest ''not found''','Fresh, permissioned knowledge','RAG for facts, fine-tuning for behavior','Measure with evals']::text[], array[71,74,75]::int[]) on conflict (slug) do update set category = excluded.category, skill_area = excluded.skill_area, difficulty = excluded.difficulty, title = excluded.title, short_answer = excluded.short_answer, explanation = excluded.explanation, code_example = excluded.code_example, real_world_example = excluded.real_world_example, follow_ups = excluded.follow_ups, related_concepts = excluded.related_concepts, key_points = excluded.key_points, day_numbers = excluded.day_numbers;
insert into public.interview_questions (id, slug, category, skill_area, difficulty, title, short_answer, explanation, code_example, real_world_example, follow_ups, related_concepts, key_points, day_numbers) values ('14043406-fde9-4d2e-a450-16189a6920f9', 'ai-chunking', 'AI Engineering', 'ai_engineering', 'intermediate', 'How do you choose a chunking strategy for RAG?', 'Chunk along the document''s natural structure (headings, paragraphs, functions), keep chunks large enough to stand alone but small enough to be specific — often a few hundred tokens with some overlap — attach metadata, and choose the final settings by measuring retrieval quality on real questions.', 'Chunks too small lose context (''it'' refers to what?); too large dilute similarity and waste tokens. Structure-aware splitting beats fixed character counts: split Markdown by headings, code by function, tables as whole units. Overlap preserves sentences cut at boundaries. Add metadata (source, title, section, date, owner) for filtering and citations. Techniques like prepending the document title or a short summary to each chunk improve retrieval. Always compare strategies with recall@k on a golden question set.', null, 'Splitting an API reference by endpoint instead of every 500 characters made ''how do I paginate orders?'' retrieve the single correct section.', array['How do you chunk tables and code?','What metadata would you store?','How do you re-index changed documents?']::text[], array['Ingestion','Metadata filtering','Recall@k']::text[], array['Respect document structure','Balance size vs specificity','Overlap at boundaries','Rich metadata','Decide with retrieval metrics']::text[], array[70,73]::int[]) on conflict (slug) do update set category = excluded.category, skill_area = excluded.skill_area, difficulty = excluded.difficulty, title = excluded.title, short_answer = excluded.short_answer, explanation = excluded.explanation, code_example = excluded.code_example, real_world_example = excluded.real_world_example, follow_ups = excluded.follow_ups, related_concepts = excluded.related_concepts, key_points = excluded.key_points, day_numbers = excluded.day_numbers;
insert into public.interview_questions (id, slug, category, skill_area, difficulty, title, short_answer, explanation, code_example, real_world_example, follow_ups, related_concepts, key_points, day_numbers) values ('f045d87c-d57b-4df7-a848-c2144421eaab', 'ai-rag-evaluation', 'AI Engineering', 'ai_engineering', 'advanced', 'How do you evaluate an LLM or RAG application?', 'Build a golden dataset of realistic questions with expected answers or sources, measure retrieval (recall@k, MRR) and generation (faithfulness, relevance, correctness) separately, use deterministic checks where possible and LLM-as-judge with clear rubrics where not, and run the suite in CI on every prompt or model change.', 'Start with 30–100 cases drawn from real or expected user questions, including tricky and unanswerable ones. Retrieval metrics tell you whether the right chunks were found; generation metrics tell you whether the answer used them faithfully. Deterministic checks (valid JSON, cites a source, contains a required fact) are cheap and stable. LLM judges scale to fuzzy criteria but need a rubric, spot-checking against human labels, and a different model than the one being judged where possible. Track scores over time and block regressions.', null, 'A team swapping to a cheaper model ran their 80-case eval, saw faithfulness drop 12 points on policy questions, and kept the larger model for that route only.', array['What are the weaknesses of LLM-as-judge?','How many eval cases do you need?','How do you include production feedback?']::text[], array['Recall@k','Faithfulness','Regression testing','Observability']::text[], array['Golden dataset incl. unanswerable cases','Separate retrieval and generation metrics','Deterministic checks first','LLM-judge with rubrics, verified by humans','Run in CI, block regressions']::text[], array[73,83,84]::int[]) on conflict (slug) do update set category = excluded.category, skill_area = excluded.skill_area, difficulty = excluded.difficulty, title = excluded.title, short_answer = excluded.short_answer, explanation = excluded.explanation, code_example = excluded.code_example, real_world_example = excluded.real_world_example, follow_ups = excluded.follow_ups, related_concepts = excluded.related_concepts, key_points = excluded.key_points, day_numbers = excluded.day_numbers;
insert into public.interview_questions (id, slug, category, skill_area, difficulty, title, short_answer, explanation, code_example, real_world_example, follow_ups, related_concepts, key_points, day_numbers) values ('3c9cd8b4-101f-4008-aae1-240d9dc4bfee', 'ai-function-calling', 'AI Engineering', 'ai_engineering', 'intermediate', 'How does tool (function) calling work?', 'You describe tools to the model with a name, description and JSON schema. When useful, the model responds with a tool call instead of text; your code runs the tool, sends the result back, and the loop continues until the model gives a final answer. The model never runs code itself — your application does.', 'Loop: send messages + tool definitions → model returns either text or one or more tool calls with arguments → validate the arguments, check permissions and execute → append results (or errors) as tool-result messages → call the model again. Good tool design matters most: clear names, precise descriptions with when-to-use guidance, small focused schemas, and error messages the model can act on. Add limits (max iterations, timeouts) and make tools idempotent so retries are safe.', 'while (steps++ < 8) {
insert into public.interview_questions (id, slug, category, skill_area, difficulty, title, short_answer, explanation, code_example, real_world_example, follow_ups, related_concepts, key_points, day_numbers) values ('208a549d-2e70-4376-a9bd-e7155aeb5ef5', 'ai-agents-vs-workflows', 'AI Engineering', 'ai_engineering', 'advanced', 'What is an AI agent, and when should you not build one?', 'An agent is an LLM that decides its own next steps in a loop — choosing tools, reading results and continuing until the goal is met. A workflow follows steps you define in code. Prefer workflows when the steps are known: they''re cheaper, faster and easier to test. Use agents only when the path genuinely can''t be predicted.', 'Common patterns from simplest to most autonomous: single prompt → prompt chain → routing → orchestrator-workers → autonomous agent. Each step up adds flexibility but also cost, latency and unpredictability. Agents need guardrails: step and token budgets, least-privilege tools, human approval for risky actions, checkpointing, tracing and evals on full trajectories. Many ''agent'' products are really well-designed workflows with one or two model-decided branches.', null, 'A ''summarize every new support ticket and tag it'' feature works best as a two-step workflow; an ''investigate why this customer''s sync failed'' tool benefits from an agent that explores logs.', array['Explain the ReAct pattern','How do you stop runaway agents?','How do you evaluate an agent?']::text[], array['Tool calling','Orchestration','Human-in-the-loop','Agent safety']::text[], array['Agent = model-directed loop','Workflow = code-directed steps','Start with the simplest pattern','Budgets, permissions, approvals','Trace and evaluate trajectories']::text[], array[77,80,82]::int[]) on conflict (slug) do update set category = excluded.category, skill_area = excluded.skill_area, difficulty = excluded.difficulty, title = excluded.title, short_answer = excluded.short_answer, explanation = excluded.explanation, code_example = excluded.code_example, real_world_example = excluded.real_world_example, follow_ups = excluded.follow_ups, related_concepts = excluded.related_concepts, key_points = excluded.key_points, day_numbers = excluded.day_numbers;
insert into public.interview_questions (id, slug, category, skill_area, difficulty, title, short_answer, explanation, code_example, real_world_example, follow_ups, related_concepts, key_points, day_numbers) values ('7889ad6a-e8da-47f3-a302-e6d62ff9186c', 'ai-mcp', 'AI Engineering', 'ai_engineering', 'intermediate', 'What is the Model Context Protocol (MCP)?', 'MCP is an open protocol that standardizes how AI applications connect to external tools and data. An MCP server exposes tools, resources and prompts; any MCP-capable client can use them, so you build an integration once instead of once per AI app.', 'Before MCP, every AI app needed custom glue for each integration. MCP defines a client–server protocol: hosts (like an IDE or chat app) run clients that connect to servers over stdio or HTTP. Servers expose tools (actions the model can call), resources (data the app can read into context) and prompts (reusable templates). Security still matters: authenticate the server, scope its permissions to the user, and treat tool output as untrusted content that could contain injected instructions.', null, 'A company publishes one MCP server for its ticketing system, and employees use it from their IDE, their chat assistant and internal agents without three separate integrations.', array['Tools vs resources vs prompts?','How do you secure an MCP server?','MCP vs plain function calling?']::text[], array['Tool calling','Agents','Prompt injection']::text[], array['Open standard for tools and data','Hosts, clients and servers','Tools, resources, prompts','Build once, use in many clients','Scope permissions and distrust tool output']::text[], array[78]::int[]) on conflict (slug) do update set category = excluded.category, skill_area = excluded.skill_area, difficulty = excluded.difficulty, title = excluded.title, short_answer = excluded.short_answer, explanation = excluded.explanation, code_example = excluded.code_example, real_world_example = excluded.real_world_example, follow_ups = excluded.follow_ups, related_concepts = excluded.related_concepts, key_points = excluded.key_points, day_numbers = excluded.day_numbers;
insert into public.interview_questions (id, slug, category, skill_area, difficulty, title, short_answer, explanation, code_example, real_world_example, follow_ups, related_concepts, key_points, day_numbers) values ('28766a0c-a334-4e0e-af33-b9e7451239fa', 'ai-cost-latency', 'AI Engineering', 'ai_engineering', 'advanced', 'How do you reduce the cost and latency of an LLM feature?', 'Measure first, then: route easy requests to smaller models, cache (prompt caching, semantic answer caching, embeddings), shorten prompts and cap output length, retrieve fewer but better chunks, batch offline work, and stream responses so users see progress immediately.', 'Trace every request to see where tokens and milliseconds go. Output tokens are usually the slowest and most expensive, so ask for concise answers and set max tokens. Prompt caching cuts cost and latency for a long, stable system prompt. A router or classifier sends simple tasks to a cheap model and hard ones to a strong model, verified by evals. Precompute work in background jobs where real-time isn''t required. Streaming doesn''t reduce total time but greatly improves perceived speed. Re-run evals after each optimization to make sure quality held.', null, 'A team cut AI spend by 60% by routing 70% of FAQ-style questions to a small model and caching the system prompt, with no measurable drop in their eval scores.', array['What is prompt caching?','How do you build a model router?','Which metrics would you put on a dashboard?']::text[], array['Observability','Evals','Streaming','Caching']::text[], array['Measure with tracing first','Model routing','Prompt and semantic caching','Shorter prompts and capped outputs','Streaming for perceived speed','Re-check quality with evals']::text[], array[85,84]::int[]) on conflict (slug) do update set category = excluded.category, skill_area = excluded.skill_area, difficulty = excluded.difficulty, title = excluded.title, short_answer = excluded.short_answer, explanation = excluded.explanation, code_example = excluded.code_example, real_world_example = excluded.real_world_example, follow_ups = excluded.follow_ups, related_concepts = excluded.related_concepts, key_points = excluded.key_points, day_numbers = excluded.day_numbers;
insert into public.interview_questions (id, slug, category, skill_area, difficulty, title, short_answer, explanation, code_example, real_world_example, follow_ups, related_concepts, key_points, day_numbers) values ('77425b8d-21c7-41d2-a156-173a8a6f64f9', 'ai-system-design-support-bot', 'AI Engineering', 'ai_engineering', 'advanced', 'Design an AI customer-support assistant for an online store.', 'Clarify scope (answer FAQs, check orders, start returns), then design: chat UI with streaming → API gateway with auth and rate limits → orchestrator that routes to RAG over help docs or to permissioned tools (order lookup, return creation) → LLM provider with fallback → human handoff, with tracing, evals, PII redaction and cost controls throughout.', 'Requirements: answer accuracy, safe actions, low latency, handoff to humans, multi-language. Data: help-center articles ingested into a vector index with metadata; order data accessed only through backend tools scoped to the signed-in customer. Flow: classify intent → RAG for policy questions with citations → tool calls for account actions, with confirmation for refunds → escalate on low confidence or user request, passing a summary to the agent. Reliability: timeouts, provider fallback, graceful ''connect me to a person''. Quality: golden eval set, feedback buttons, weekly review of failed conversations. Security: prompt-injection defenses, authorization in the backend, PII redaction in logs.', null, 'This is the architecture behind most modern support bots: retrieval for knowledge, tools for actions, humans for the edge cases.', array['How do you decide when to hand off to a human?','How do you prevent wrong refunds?','How would you measure success after launch?']::text[], array['RAG','Tool calling','Prompt injection','Observability']::text[], array['Clarify scope and actions','RAG for knowledge, tools for actions','Backend authorization + confirmations','Human handoff with context','Evals, tracing, fallbacks and PII handling']::text[], array[88,90]::int[]) on conflict (slug) do update set category = excluded.category, skill_area = excluded.skill_area, difficulty = excluded.difficulty, title = excluded.title, short_answer = excluded.short_answer, explanation = excluded.explanation, code_example = excluded.code_example, real_world_example = excluded.real_world_example, follow_ups = excluded.follow_ups, related_concepts = excluded.related_concepts, key_points = excluded.key_points, day_numbers = excluded.day_numbers;
insert into public.project_milestones (id, slug, position, title, description, target_day, tasks) values ('ea31a6be-61b6-4db0-ab3c-ea46dc54c730', 'ai-rag-assistant', 13, 'AI help assistant (RAG)', 'Let customers ask questions about services and policies, answered from your own docs with citations.', 74, '[{"id":"ai-rag-assistant-1","title":"Ingest help docs and service descriptions into pgvector"},{"id":"ai-rag-assistant-2","title":"Ask endpoint with citations and an honest ''I don''t know''"},{"id":"ai-rag-assistant-3","title":"Per-workspace access control on retrieval"},{"id":"ai-rag-assistant-4","title":"30-question eval set with recall@5 in CI"}]'::jsonb) on conflict (slug) do update set position = excluded.position, title = excluded.title, description = excluded.description, target_day = excluded.target_day, tasks = excluded.tasks;
insert into public.project_milestones (id, slug, position, title, description, target_day, tasks) values ('531169d7-698a-46b2-a905-3957ea21e840', 'ai-booking-agent', 14, 'AI booking agent (tools)', 'An assistant that can search availability, book, reschedule and cancel through safe tools.', 81, '[{"id":"ai-booking-agent-1","title":"Search, book, reschedule and cancel tools with Zod-validated inputs"},{"id":"ai-booking-agent-2","title":"Confirmation step before any destructive action"},{"id":"ai-booking-agent-3","title":"Step, token and spend limits on the agent loop"},{"id":"ai-booking-agent-4","title":"Audit log of every agent action"}]'::jsonb) on conflict (slug) do update set position = excluded.position, title = excluded.title, description = excluded.description, target_day = excluded.target_day, tasks = excluded.tasks;
insert into public.project_milestones (id, slug, position, title, description, target_day, tasks) values ('2ecf6bca-352a-44c6-a8f7-3ea111ee928d', 'ai-production', 15, 'AI in production', 'Make the AI features observable, affordable and demo-ready.', 89, '[{"id":"ai-production-1","title":"Tracing for every LLM call (latency, tokens, cost)"},{"id":"ai-production-2","title":"Model routing or prompt caching with before/after numbers"},{"id":"ai-production-3","title":"User feedback buttons wired to a dashboard"},{"id":"ai-production-4","title":"Case study + demo video of the AI features"}]'::jsonb) on conflict (slug) do update set position = excluded.position, title = excluded.title, description = excluded.description, target_day = excluded.target_day, tasks = excluded.tasks;
